// AFTERZERO head_b: materials. Skin = MeshPhysicalMaterial patched with
//  - wrap-lit, per-channel diffuse (subsurface approximation with a warm terminator),
//  - back-light translucency for thin parts (ears, nostrils, lids) from a per-vertex thickness,
//  - per-vertex SDF ambient occlusion on indirect light, specular and (partly) direct light,
//  - a tiling pore/micro detail normal blended over the baked normal map.
// Eyes = sclera/iris material with lid-contact occlusion computed in socket space, plus an
// additive glossy cornea shell. All textures are generated by our own code.

import * as THREE from 'three';

const { sqrt, floor, sin, cos, PI, pow, abs, min, max, exp } = Math;

function hash2(ix, iy, s) {
  let h = Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(s, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
function vnoiseT(x, y, s, P) { // tileable value noise with period P
  const ix = floor(x), iy = floor(y), fx = x - ix, fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
  const w = (i, j) => hash2(((i % P) + P) % P, ((j % P) + P) % P, s);
  const a = w(ix, iy), b = w(ix + 1, iy), c = w(ix, iy + 1), d = w(ix + 1, iy + 1);
  return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
}

let DETAIL = null;
/** global tiling skin micro-detail normal map (pores + fine cross-hatched lines), built once */
export function skinDetailNormal() {
  if (DETAIL) return DETAIL;
  const R = 256, H = new Float32Array(R * R);
  const C = 22; // pore cells per tile
  for (let y = 0; y < R; y++) for (let x = 0; x < R; x++) {
    const u = x / R * C, v = y / R * C;
    const ix = floor(u), iy = floor(v);
    let d1 = 9;
    for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) {
      const cx = ix + i, cy = iy + j;
      const wx = ((cx % C) + C) % C, wy = ((cy % C) + C) % C;
      const px = cx + 0.15 + 0.7 * hash2(wx, wy, 3), py = cy + 0.15 + 0.7 * hash2(wx, wy, 4);
      const dd = (u - px) * (u - px) + (v - py) * (v - py);
      if (dd < d1) d1 = dd;
    }
    const pore = -(Math.max(0, 1 - sqrt(d1) / 0.28) ** 2);
    // fine skin lines (two crossing directions)
    const l1 = vnoiseT((x + y) / R * 48, (x - y) / R * 6, 7, 48) - 0.5;
    const l2 = vnoiseT((x - y * 0.6) / R * 40, (y + x * 0.3) / R * 5, 8, 40) - 0.5;
    const n = vnoiseT(x / R * 64, y / R * 64, 9, 64) - 0.5;
    H[y * R + x] = pore * 0.8 + (abs(l1) < 0.08 ? -0.25 : 0) + (abs(l2) < 0.07 ? -0.18 : 0) + n * 0.25;
  }
  const D = new Uint8Array(R * R * 4);
  for (let y = 0; y < R; y++) for (let x = 0; x < R; x++) {
    const hl = H[y * R + (x + R - 1) % R], hr = H[y * R + (x + 1) % R], hd = H[((y + R - 1) % R) * R + x], hu = H[((y + 1) % R) * R + x];
    let nx = -(hr - hl) * 1.4, ny = -(hu - hd) * 1.4, nz = 1;
    const l = sqrt(nx * nx + ny * ny + nz * nz);
    const o = (y * R + x) * 4;
    D[o] = (nx / l * 0.5 + 0.5) * 255; D[o + 1] = (ny / l * 0.5 + 0.5) * 255; D[o + 2] = (nz / l * 0.5 + 0.5) * 255; D[o + 3] = 255;
  }
  const t = new THREE.DataTexture(D, R, R, THREE.RGBAFormat);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearMipmapLinearFilter;
  t.generateMipmaps = true; t.anisotropy = 4; t.needsUpdate = true;
  DETAIL = t;
  return t;
}

function dataTex(arr, R, srgb) {
  const t = new THREE.DataTexture(arr, R, R, THREE.RGBAFormat);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.ClampToEdgeWrapping;
  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearMipmapLinearFilter; t.generateMipmaps = true; t.anisotropy = 4;
  t.needsUpdate = true;
  return t;
}

/**
 * @param tex  bakeSkin output (albedo, normal, rough, R, RR) or null for untextured low detail
 */
export function makeSkinMaterial(tex, opts = {}) {
  const mat = new THREE.MeshPhysicalMaterial({
    color: 0xffffff, roughness: 1.0, metalness: 0, ior: 1.4, specularIntensity: 0.62,
    sheen: 0.12, sheenRoughness: 0.5, sheenColor: new THREE.Color(0.55, 0.36, 0.3),
  });
  if (tex) {
    mat.map = dataTex(tex.albedo, tex.R, true);
    mat.normalMap = dataTex(tex.normal, tex.R, false);
    mat.normalScale = new THREE.Vector2(opts.normalScale ?? 0.9, opts.normalScale ?? 0.9);
    mat.roughnessMap = dataTex(tex.rough, tex.RR, false);
  } else {
    mat.color = new THREE.Color(opts.color ?? 0xc08a64);
    mat.roughness = 0.55;
  }
  const detail = opts.detailNormal !== false && tex ? skinDetailNormal() : null;
  const U = {
    uWrap: { value: new THREE.Vector3(0.3, 0.14, 0.09) },
    uSSSColor: { value: new THREE.Color(1.0, 0.32, 0.18) },
    uTransl: { value: opts.transl ?? 0.9 },
    uDetail: { value: detail },
    uDetailRepeat: { value: opts.detailRepeat ?? 9.0 },
    uDetailScale: { value: opts.detailScale ?? 0.18 },
    uAOStrength: { value: opts.aoStrength ?? 1.0 },
  };
  mat.userData.uniforms = U;
  mat.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec2 skinAttr;\nvarying vec2 vSkin;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSkin = skinAttr;');
    const lp = THREE.ShaderChunk.lights_physical_pars_fragment.replace(
      'reflectedLight.directDiffuse += irradiance * BRDF_Lambert( material.diffuseColor );',
      `{
        float nlr = dot( geometryNormal, directLight.direction );
        vec3 wrapNL = clamp( ( vec3( nlr ) + uWrap ) / ( 1.0 + uWrap ), 0.0, 1.0 );
        wrapNL *= wrapNL * ( 3.0 - 2.0 * wrapNL ) * 0.35 + wrapNL * 0.65;
        float occ = mix( 1.0, vSkin.x, 0.55 * uAOStrength );
        reflectedLight.directDiffuse += wrapNL * directLight.color * BRDF_Lambert( material.diffuseColor ) * occ;
        // thin-part translucency (ears, nostrils, lids): light from behind bleeds through red
        float back = pow( saturate( dot( geometryViewDir, - directLight.direction ) * 0.6 + 0.4 ), 3.0 );
        float thin = smoothstep( 0.15, 0.85, vSkin.y );
        reflectedLight.directDiffuse += directLight.color * material.diffuseColor * uSSSColor * ( thin * back * uTransl * 0.6 + saturate( - nlr ) * 0.06 );
      }`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
varying vec2 vSkin;
uniform vec3 uWrap; uniform vec3 uSSSColor; uniform float uTransl; uniform float uAOStrength;
${detail ? 'uniform sampler2D uDetail; uniform float uDetailRepeat; uniform float uDetailScale;' : ''}`)
      .replace('#include <lights_physical_pars_fragment>', lp)
      .replace('#include <aomap_fragment>', `
        {
          float ambientOcclusion = mix( 1.0, vSkin.x, uAOStrength );
          reflectedLight.indirectDiffuse *= ambientOcclusion;
          #if defined( USE_CLEARCOAT )
            clearcoatSpecularIndirect *= ambientOcclusion;
          #endif
          #if defined( USE_SHEEN )
            sheenSpecularIndirect *= ambientOcclusion;
          #endif
          #if defined( USE_ENVMAP ) && defined( STANDARD )
            float dotNV = saturate( dot( geometryNormal, geometryViewDir ) );
            reflectedLight.indirectSpecular *= computeSpecularOcclusion( dotNV, ambientOcclusion, material.roughness );
          #endif
        }`);
    if (detail) {
      sh.fragmentShader = sh.fragmentShader.replace('#include <normal_fragment_maps>', `
        #ifdef USE_NORMALMAP_TANGENTSPACE
          vec3 mapN = texture2D( normalMap, vNormalMapUv ).xyz * 2.0 - 1.0;
          mapN.xy *= normalScale;
          vec3 detN = texture2D( uDetail, vNormalMapUv * vec2( uDetailRepeat * 2.0, uDetailRepeat ) ).xyz * 2.0 - 1.0;
          mapN = normalize( vec3( mapN.xy + detN.xy * uDetailScale, mapN.z ) );
          normal = normalize( tbn * mapN );
        #endif`);
    }
  };
  mat.customProgramCacheKey = () => 'head_b_skin_' + (detail ? 'd' : 'n') + (tex ? 't' : 'u');
  return mat;
}

// ---------------------------------------------------------------------------------------------
// Eyes
const EYE_TEX = new Map();
function irisColorLin(hex) { return [(hex >> 16 & 255) / 255, (hex >> 8 & 255) / 255, (hex & 255) / 255]; }

/** eye texture: polar layout. u = angle around the eye axis, v = angular distance from the axis (0 centre .. 1 back) */
export function eyeTexture(eyeColor, seed = 1) {
  const key = eyeColor + ':' + seed;
  if (EYE_TEX.has(key)) return EYE_TEX.get(key);
  const W = 512, H = 256, D = new Uint8Array(W * H * 4);
  const ic = irisColorLin(eyeColor);
  const lumI = 0.3 * ic[0] + 0.59 * ic[1] + 0.11 * ic[2];
  // limbus at angle alpha (sclera sphere), the texture v covers 0..PI
  const limbV = 0.505 / PI;          // ~29 deg
  const pupV = limbV * 0.36;
  const s = seed * 13 + 5;
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const a = x / W * 2 * PI, v = (y + 0.5) / H; // v: 0 at the front pole
    const r = v / limbV;                         // 0 centre .. 1 limbus
    let R, G, B;
    if (r < 1.06) {
      // iris: radial fibres, collarette, crypts, darker limbal ring, pupil
      const fib = vnoiseT(x / W * 180, r * 6, s, 180) * 0.6 + vnoiseT(x / W * 90, r * 14, s + 1, 90) * 0.4;
      const crypt = vnoiseT(x / W * 40, r * 4, s + 2, 40);
      const collar = Math.exp(-(((r - 0.48) / 0.07) ** 2));
      let k = 0.75 + 0.55 * (fib - 0.5) - 0.25 * Math.max(0, crypt - 0.62) * 3;
      // inner ring warmer / lighter (hazel/amber near the pupil), outer darker
      const inner = Math.exp(-(((r - 0.42) / 0.16) ** 2));
      R = ic[0] * k + 0.12 * inner * (0.6 - lumI); G = ic[1] * k + 0.07 * inner * (0.6 - lumI); B = ic[2] * k;
      R += 0.08 * collar; G += 0.07 * collar; B += 0.05 * collar;
      const limb = Math.max(0, (r - 0.8) / 0.2);
      const lr = 1 - 0.75 * Math.min(1, limb * limb);
      R *= lr; G *= lr; B *= lr;
      // pupil
      const pr = (v / pupV);
      const pm = 1 / (1 + Math.exp((pr - 1) * 30));
      R = R * (1 - pm) + 0.012 * pm; G = G * (1 - pm) + 0.01 * pm; B = B * (1 - pm) + 0.01 * pm;
      // blend to sclera at the limbus
      const sb = Math.max(0, Math.min(1, (r - 1.0) / 0.06));
      const sc = 0.82;
      R = R * (1 - sb) + sc * 0.95 * sb; G = G * (1 - sb) + sc * 0.9 * sb; B = B * (1 - sb) + sc * 0.86 * sb;
    } else {
      // sclera: off-white, warmer/greyer toward the back, faint veins concentrated at the sides
      const back = Math.min(1, (v - limbV) / 0.45);
      const side = Math.abs(cos(a)); // horizontal sides (corners) carry more vessels
      R = 0.84 - 0.1 * back; G = 0.8 - 0.14 * back; B = 0.76 - 0.16 * back;
      const vn = vnoiseT(x / W * 60, v * 22, s + 3, 60);
      const vein = Math.max(0, 1 - Math.abs(vn - 0.5) / 0.025) * (0.25 + 0.75 * side) * Math.min(1, back * 2.5 + 0.1);
      const vein2 = Math.max(0, 1 - Math.abs(vnoiseT(x / W * 120, v * 40, s + 4, 120) - 0.5) / 0.02) * side * back;
      const vv = Math.min(1, vein * 0.55 + vein2 * 0.35);
      R = R * (1 - vv) + 0.62 * vv; G = G * (1 - vv) + 0.2 * vv; B = B * (1 - vv) + 0.2 * vv;
      const mott = vnoiseT(x / W * 24, v * 8, s + 5, 24) - 0.5;
      R += 0.03 * mott; G += 0.025 * mott; B += 0.02 * mott;
    }
    const o = (y * W + x) * 4;
    const toS = c => Math.round(Math.max(0, Math.min(1, c <= 0.0031308 ? c * 12.92 : 1.055 * pow(c, 1 / 2.4) - 0.055)) * 255);
    D[o] = toS(R); D[o + 1] = toS(G); D[o + 2] = toS(B); D[o + 3] = 255;
  }
  const t = new THREE.DataTexture(D, W, H, THREE.RGBAFormat);
  t.colorSpace = THREE.SRGBColorSpace; t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.ClampToEdgeWrapping;
  t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter; t.generateMipmaps = true; t.anisotropy = 4; t.needsUpdate = true;
  EYE_TEX.set(key, t);
  return t;
}

const LID_GLSL = `
uniform vec4 uFisA; uniform vec4 uFisB; uniform float uSide; uniform float uBlink;
float lidBump( float t, float p ) { if ( t <= 0.0 || t >= 1.0 ) return 0.0; return sin( 3.14159265 * pow( t, log( 0.5 ) / log( p ) ) ); }
// lid margins (elevation angles) at azimuth az around the eye centre: x = upper, y = lower, z = t
vec3 lidUL( float az ) {
  float t = ( az - uFisA.x ) / ( uFisA.y - uFisA.x );
  float tc = clamp( t, 0.0, 1.0 );
  float base = mix( uFisA.z, uFisA.w, tc );
  float up = base + uFisB.x * pow( max( lidBump( tc, uFisB.z ), 0.0 ), 0.78 );
  float lo = base - uFisB.y * pow( max( lidBump( tc, uFisB.w ), 0.0 ), 0.95 );
  return vec3( up, lo, t );
}`;

function lidUniforms(lid) {
  return {
    uGaze: { value: new THREE.Matrix3() },
    uFisA: { value: new THREE.Vector4(lid.am, lid.al, lid.bm, lid.bl) },
    uFisB: { value: new THREE.Vector4(lid.hu, lid.hl, lid.pu, lid.pl) },
    uSide: { value: lid.side },
    uBlink: { value: 0 },
  };
}

/**
 * Eyeball material with lid-contact occlusion (lid margins from the model's fissure angles).
 * lid: { am, al, bm, bl, hu, hl, pu, pl, side }
 */
export function makeEyeMaterial(tex, lid) {
  const mat = new THREE.MeshPhysicalMaterial({ map: tex, roughness: 0.3, metalness: 0, ior: 1.38, specularIntensity: 0.5 });
  const U = lidUniforms(lid);
  mat.userData.uniforms = U;
  mat.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nuniform mat3 uGaze;\nvarying vec3 vSock;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSock = uGaze * position;');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
varying vec3 vSock;
${LID_GLSL}
float lidOcc() {
  vec3 p = vSock; p.x *= uSide;
  float az = atan( p.x, p.z ), el = atan( p.y, length( p.xz ) );
  vec3 L = lidUL( az );
  float up = mix( L.x, L.y + 0.22 * ( L.x - L.y ), uBlink );
  float dU = ( up - el ) * 12.0, dL = ( el - L.y ) * 12.0;          // ~ mm at the eye surface
  float o = smoothstep( 0.0, 2.8, dU ) * 0.62 + 0.38;               // the upper lid and lashes shade the eye
  o *= smoothstep( 0.0, 1.0, dL ) * 0.25 + 0.75;
  o *= smoothstep( 0.0, 0.22, min( L.z, 1.0 - L.z ) ) * 0.45 + 0.55; // corners
  return o;
}`)
      .replace('#include <aomap_fragment>', `
        float lo_ = lidOcc();
        reflectedLight.indirectDiffuse *= lo_;
        reflectedLight.directDiffuse *= lo_ * lo_;
        reflectedLight.directSpecular *= lo_ * lo_;
        reflectedLight.indirectSpecular *= lo_;`);
  };
  mat.customProgramCacheKey = () => 'head_b_eye2';
  return mat;
}

/** additive glossy cornea / tear film shell: only reflections are added on top of the eye */
export function makeCorneaMaterial(lid) {
  const mat = new THREE.MeshPhysicalMaterial({ color: 0x000000, roughness: 0.05, metalness: 0, ior: 1.376, specularIntensity: 1.0, transparent: true, depthWrite: false });
  mat.blending = THREE.CustomBlending; mat.blendSrc = THREE.OneFactor; mat.blendDst = THREE.OneFactor; mat.blendEquation = THREE.AddEquation;
  const U = lidUniforms(lid);
  mat.userData.uniforms = U;
  mat.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nuniform mat3 uGaze;\nvarying vec3 vSock;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSock = uGaze * position;');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
varying vec3 vSock;
${LID_GLSL}`)
      .replace('#include <aomap_fragment>', `
        {
          vec3 p = vSock; p.x *= uSide;
          float az = atan( p.x, p.z ), el = atan( p.y, length( p.xz ) );
          vec3 L = lidUL( az );
          float up = mix( L.x, L.y + 0.22 * ( L.x - L.y ), uBlink );
          float o = smoothstep( 0.0, 1.6, ( up - el ) * 12.0 ) * 0.85 + 0.15;
          reflectedLight.directSpecular *= o;
          reflectedLight.indirectSpecular *= o * 0.9;
        }`);
  };
  mat.customProgramCacheKey = () => 'head_b_cornea2';
  return mat;
}
